const body = $input.first().json.body || $input.first().json;
const doc = body.doc || body;

return [{
  json: {
    invoice_id: doc.name,
    customer: doc.customer,
    customer_name: doc.customer_name,
    mobile_no: (doc.contact_mobile || '').replace(/\D/g, ''),
    endereco: {
      cep: (doc.shipping_address_details?.pincode || '').replace(/\D/g, ''),
      rua: doc.shipping_address_details?.address_line1 || '',
      numero: doc.shipping_address_details?.address_line2 || '',
      bairro: doc.shipping_address_details?.county || '',
      cidade: doc.shipping_address_details?.city || '',
      estado: doc.shipping_address_details?.state || ''
    },
    peso: doc.total_net_weight || 0.5,
    altura: doc.custom_altura_cm || 10,
    largura: doc.custom_largura_cm || 15,
    comprimento: doc.custom_comprimento_cm || 20,
    valor_declarado: doc.grand_total || 0
  }
}];

// Transportadoras excluídas: Correios (1,2) e Azul Cargo (7)
const EXCLUIDOS = [1, 2, 7];
const CUSTO_MAX_POR_DIA = 0.55;

const cotacoes = $input.first().json;

const validas = cotacoes.filter(c =>
  !EXCLUIDOS.includes(c.id) &&
  !c.error &&
  c.price &&
  c.delivery_range
);

if (validas.length == 0) throw new Error('Nenhuma transportadora válida disponível');

validas.sort((a, b) => parseFloat(a.price) - parseFloat(b.price));

const base = validas[0];
const prazo_base = base.delivery_range.max;
const preco_base = parseFloat(base.price);

let escolhida = base;

for (const c of validas) {
  const preco = parseFloat(c.price);
  const prazo = c.delivery_range.max;

  if (prazo < prazo_base) {
    const dias_reduzidos = prazo_base - prazo;
    const custo_extra = preco - preco_base;
    const custo_por_dia = custo_extra / dias_reduzidos;

    if (custo_por_dia <= CUSTO_MAX_POR_DIA) {
      if (prazo < escolhida.delivery_range.max ||
        (prazo == escolhida.delivery_range.max && preco < parseFloat(escolhida.price))) {
        escolhida = c;
      }
    }
  }
}

return [{
  json: {
    transportadora_id: escolhida.id,
    transportadora_nome: escolhida.name,
    preco: parseFloat(escolhida.price),
    prazo_max: escolhida.delivery_range.max,
    invoice_id: $node['Extrai Dados da Fatura'].json.invoice_id,
    customer_name: $node['Extrai Dados da Fatura'].json.customer_name,
    mobile_no: $node['Extrai Dados da Fatura'].json.mobile_no,
    endereco: $node['Extrai Dados da Fatura'].json.endereco,
    peso: $node['Extrai Dados da Fatura'].json.peso,
    altura: $node['Extrai Dados da Fatura'].json.altura,
    largura: $node['Extrai Dados da Fatura'].json.largura,
    comprimento: $node['Extrai Dados da Fatura'].json.comprimento,
    valor_declarado: $node['Extrai Dados da Fatura'].json.valor_declarado
  }
}];

const saldo = parseFloat($json.balance || 0);
const preco = $node['Selecciona Transportadora'].json.preco;

if (saldo < preco) {
  throw new Error(`Saldo insuficiente no Melhor Envio. Saldo: R$${saldo.toFixed(2)} | Frete: R$${preco.toFixed(2)}. Recarregue a carteira.`);
}

return [{ json: { saldo_ok: true, saldo } }];

