const order = $node["Recombina Invoices e Rastreio"].json.tracking;
const invoice = $json;
const order_id = invoice.custom_melhorenvio_order_id;
const tracking_data = order[order_id];

if (!tracking_data) return [];

const status = tracking_data.status || '';
const events = tracking_data.tracking || tracking_data.volumes?.[0]?.tracking || [];
const last_event = events.slice(-1)[0]?.description || '';

const MENSAGENS = {
  'posted':           '📬 Seu pedido *#' + invoice.name + '* foi postado e está a caminho!',
  'in_transit':       '🚚 Seu pedido *#' + invoice.name + '* está em trânsito. Último evento: ' + last_event,
  'out_for_delivery': '🏃 Seu pedido *#' + invoice.name + '* *saiu para entrega hoje!* Fique atento.',
  'delivered':        '✅ Seu pedido *#' + invoice.name + '* foi *entregue com sucesso!* Qualquer dúvida, estamos aqui.'
};

const mensagem = MENSAGENS[status];
if (!mensagem) return [];

return [{
  json: {
    invoice_id: invoice.name,
    status,
    mensagem,
    mobile_no: (invoice.contact_mobile || '').replace(/\D/g, ''),
    customer_name: invoice.customer_name,
    entregue: status == 'delivered' ? 1 : 0
  }
}];

const invoices = $json.data || [];
const ids = invoices.map(i => i.custom_melhorenvio_order_id).filter(Boolean);
return [{ json: { ids, invoices } }];

